    }

    condition {
      test     = "StringLike"
      variable = "aws:PrincipalArn"

      values = ["arn:aws:iam::${var.deployment_accountid}:role/${var.prowler_iamrole_name}"]
    }
  }
}

data "aws_iam_policy_document" "prowlers3_bucket_policy" {
  statement {
    sid    = "AllowGetPutListObject"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:PutObjectAcl"
    ]

    resources = [
      aws_s3_bucket.prowler_bucket.arn,
      "${aws_s3_bucket.prowler_bucket.arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalOrgId"

      values = [data.aws_organizations_organization.org.id]
    }
  }

  statement {
    sid    = "DenyNonSSLRequests"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.prowler_bucket.arn,
      "${aws_s3_bucket.prowler_bucket.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"

      values = [
        "false",
      ]
    }
  }

  statement {
    sid    = "DenyIncorrectEncryptionHeader"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.prowler_bucket.arn}/*",
    ]

    condition {
      test     = "Null"
      variable = "s3:x-amz-server-side-encryption"

      values = [
        "false",
      ]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"

      values = [
        "AES256",
      ]
    }
  }
}

